    assert slugify("Hello   World") == "hello-world"


def test_slugify_punctuation_only():
    assert slugify("!!!") == ""


def test_slugify_special_symbols():
    assert slugify("a@b#c$d") == "a-b-c-d"


def test_slugify_leading_trailing_special_chars():
    assert slugify("--hello--") == "hello"


def test_slugify_numeric_only():
    assert slugify("12345") == "12345"


def test_slugify_alphanumeric_mixed():
    assert slugify("Test123") == "test123"


def test_slugify_unicode_letters():
    # isalnum() returns True for unicode letters/digits in Python 3
    assert slugify("Café") == "café"


def test_slugify_all_special_chars():
    assert slugify("!!!???") == ""


def test_slugify_single_character():
    assert slugify("A") == "a"


def test_slugify_hyphens_in_input():
    assert slugify("already-slug") == "already-slug"


def test_slugify_consecutive_hyphens_input():
    assert slugify("a---b") == "a-b"


def test_slugify_tab_and_newline():
    assert slugify("hello\tworld\n") == "hello-world"


def test_slugify_underscore_replaced():
    assert slugify("snake_case") == "snake-case"


def test_slugify_period_replaced():
    assert slugify("file.name.txt") == "file-name-txt"


def test_slugify_long_text():
    text = "A" * 100
    assert slugify(text) == "a" * 100


def test_slugify_alternating_special_and_alnum():
    assert slugify("a!b@c#d") == "a-b-c-d"


def test_slugify_only_whitespace():
    assert slugify("   ") == ""


def test_slugify_single_space():
    assert slugify(" ") == ""


def test_slugify_digit_and_special_mixed():
    assert slugify("1!2@3#4") == "1-2-3-4"

