import pytest

from string_utils import mask_email


def test_mask_email_single_char_local():
    assert mask_email("a@b.com") == "a@b.com"


def test_mask_email_two_char_local():
    assert mask_email("ab@example.com") == "a*@example.com"


def test_mask_email_long_local():
    assert mask_email("abcdefgh@example.com") == "a*******@example.com"


def test_mask_email_empty_local_raises():
    with pytest.raises(ValueError):
        mask_email("@example.com")


def test_mask_email_empty_domain_raises():
    with pytest.raises(ValueError):
        mask_email("user@")


def test_mask_email_missing_at_raises():
    with pytest.raises(ValueError):
        mask_email("userexample.com")


def test_mask_email_multiple_at_raises():
    # partition takes first '@', so "a@b@c.com" -> local="a", domain="b@c.com"
    # This is valid per implementation; domain is non-empty
    assert mask_email("a@b@c.com") == "a@b@c.com"


def test_mask_email_special_chars_in_local():
    assert mask_email("user.name+tag@example.com") == "u************@example.com"


def test_mask_email_single_char_domain():
    assert mask_email("ab@c") == "a*@c"


def test_mask_email_preserves_domain_case():
    assert mask_email("user@Example.COM") == "u***@Example.COM"

