    assert integer_sqrt(1000000) == 1000


def test_isqrt_just_below_square():
    assert integer_sqrt(999999) == 999


def test_isqrt_just_above_square():
    assert integer_sqrt(1000001) == 1000


def test_isqrt_big_non_square():
    assert integer_sqrt(999999999) == 31622

