import pytest

from numeric import moving_average


def test_empty_values_returns_empty():
    assert moving_average([], 1) == []


def test_window_zero_raises():
    with pytest.raises(ValueError):
        moving_average([1, 2, 3], 0)


def test_window_negative_raises():
    with pytest.raises(ValueError):
        moving_average([1, 2, 3], -1)


def test_window_larger_than_values_raises():
    with pytest.raises(ValueError):
        moving_average([1, 2], 3)


def test_window_equals_len_returns_single_mean():
    assert moving_average([1, 2, 3, 4], 4) == [2.5]


def test_window_one_returns_original_values_as_floats():
    assert moving_average([1, 2, 3], 1) == [1.0, 2.0, 3.0]


def test_single_element_window_one():
    assert moving_average([7], 1) == [7.0]


def test_negative_values():
    assert moving_average([-1, -2, -3], 2) == [-1.5, -2.5]


def test_mixed_positive_negative():
    assert moving_average([1, -1, 1, -1], 2) == [0.0, 0.0, 0.0]


def test_float_values():
    assert moving_average([1.5, 2.5, 3.5], 2) == [2.0, 3.0]


def test_large_window_result_length():
    result = moving_average(list(range(1, 11)), 5)
    assert len(result) == 6
    assert result[0] == 3.0
    assert result[1] == 4.0
    assert result[2] == 5.0
    assert result[3] == 6.0
    assert result[4] == 7.0
    assert result[5] == 8.0


def test_window_boundary_one():
    assert moving_average([10, 20, 30], 1) == [10.0, 20.0, 30.0]


def test_window_boundary_full_length():
    assert moving_average([10, 20, 30], 3) == [20.0]


