import pytest

from containers import most_frequent


def test_most_frequent_empty_raises_valueerror():
    with pytest.raises(ValueError, match="empty input"):
        most_frequent([])


def test_most_frequent_single_element():
    assert most_frequent([42]) == 42


def test_most_frequent_unique_elements_tie_first_occurrence():
    # All elements appear exactly once; first occurrence wins
    assert most_frequent([1, 2, 3]) == 1


def test_most_frequent_tie_breaking_by_first_occurrence():
    # "a" and "b" both appear twice; "a" appears first, so it wins
    assert most_frequent(["b", "a", "a", "b"]) == "b"  # b appears first in the list


def test_most_frequent_most_frequent_wins_over_earlier():
    # "a" appears first but "b" appears more often
    assert most_frequent(["a", "b", "b", "b"]) == "b"


def test_most_frequent_integer_elements():
    assert most_frequent([3, 1, 3, 2, 3]) == 3


def test_most_frequent_mixed_hashable_types():
    assert most_frequent([1, "1", 1, 1, "1"]) == 1


def test_most_frequent_two_elements_one_dominates():
    assert most_frequent(["x", "y", "y", "y", "y"]) == "y"

