import pytest
from parsers import parse_csv_line


def test_simple_unquoted_fields():
    assert parse_csv_line("a,b,c") == ["a", "b", "c"]


def test_empty_line():
    assert parse_csv_line("") == [""]


def test_single_field():
    assert parse_csv_line("hello") == ["hello"]


def test_quoted_field_with_comma():
    assert parse_csv_line('"a,b",c') == ["a,b", "c"]


def test_quoted_field_with_escaped_quote():
    # "" inside quotes is one literal quote
    assert parse_csv_line('"a""b",c') == ['a"b', "c"]


def test_quoted_field_with_escaped_quote_at_end():
    assert parse_csv_line('"a"""') == ['a"']


def test_multiple_escaped_quotes():
    assert parse_csv_line('"a""""b"') == ['a""b']


def test_unquoted_field_with_spaces():
